    # Initialize the set of numbers that can be written on the blackboard
    possible_numbers = {a for a in A}

    # Perform the operations to generate new numbers
    while True:
        new_numbers = set()
        for num in possible_numbers:
            if num * 2 <= X:
                new_numbers.add(num * 2)
            for other_num in possible_numbers:
                if num ^ other_num <= X:
                    new_numbers.add(num ^ other_num)
        if not new_numbers:
            break
        possible_numbers.update(new_numbers)

    # Count the number of unique numbers not exceeding X
    result = len([num for num in possible_numbers if num <= X])

    print(result)

