    MOD = 998244353
    max_val = int(X, 2)
    dp = {int(a, 2) for a in A}

    while True:
        new_dp = dp.copy()
        for num in dp:
            if num * 2 <= max_val:
                new_dp.add(num * 2)
            for other_num in dp:
                if num ^ other_num <= max_val:
                    new_dp.add(num ^ other_num)
        if new_dp == dp:
            break
        dp = new_dp

    return len(dp) % MOD

