def count_distinct_numbers(N: int, X: int, A: List[int]) -> int:
    MOD = 998244353
    max_val = X + 1
    dp = [False] * max_val
    for num in A:
        dp[num] = True

    stack = list(A)
    while stack:
        current = stack.pop()
        if current * 2 >= max_val:
            continue
        if not dp[current * 2]:
            dp[current * 2] = True
            stack.append(current * 2)

    for i in range(max_val):
        for j in range(i, max_val):
            if i ^ j >= max_val:
                continue
            if not dp[i ^ j]:
                dp[i ^ j] = True
                stack.append(i ^ j)

    return sum(dp) % MOD

